exercises.solution:
#include <stdio.h>

int main(void)
{
    int bags = 7;
    double price = 55.5;
    const char *crop = "maize";
    printf("%d bags of %s\n", bags, crop);
    printf("price %.2f\n", price);
    return 0;
}
